Tool response:
Tool: find_unassigned_critical_orders
Description: Retrieve up to 8 unassigned critical orders whose time windows start within the next 90 minutes 
in the specified district.
Parameters:
    {
      "type": "object",
      "properties": {
        "district_id": {
          "type": "integer",
          "description": "ID of the district (Chicago Loop)",
          "title": "District Id"
        },
        "time_window_minutes": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Time window in minutes from now",
          "default": 90,
          "title": "Time Window Minutes"
        },
        "limit": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Maximum number of orders to return",
          "default": 8,
          "title": "Limit"
        }
      },
      "required": [
        "district_id"
      ]
    }

Tool response:
Tool: find_available_drivers
Description: Retrieve drivers who are currently available and located in the Chicago Loop district, 
ensuring they are within their shift hours.
Parameters:
    {
      "type": "object",
      "properties": {
        "district_id": {
          "type": "integer",
          "description": "ID of the district (Chicago Loop)",
          "title": "District Id"
        },
        "limit": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Maximum number of drivers to return",
          "title": "Limit"
        }
      },
      "required": [
        "district_id"
      ]
    }

Tool response:
Tool: find_available_vehicles
Description: Retrieve vehicles that are available and located in the Chicago Loop district 
with battery levels above the threshold.
Parameters:
    {
      "type": "object",
      "properties": {
        "district_id": {
          "type": "integer",
          "description": "ID of the district (Chicago Loop)",
          "title": "District Id"
        },
        "battery_threshold": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "description": "Minimum battery level percentage",
          "default": 20.0,
          "title": "Battery Threshold"
        },
        "limit": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Maximum number of vehicles to return",
          "title": "Limit"
        }
      },
      "required": [
        "district_id"
      ]
    }

Tool response:
Tool: assign_orders_to_route
Description: Create a new route assigning the given orders to a driver and vehicle combination, 
ensuring constraints like max stops and battery levels are respected.
Parameters:
    {
      "type": "object",
      "properties": {
        "driver_id": {
          "type": "integer",
          "title": "Driver Id"
        },
        "vehicle_id": {
          "type": "integer",
          "title": "Vehicle Id"
        },
        "order_ids": {
          "items": {
            "type": "integer"
          },
          "type": "array",
          "title": "Order Ids"
        }
      },
      "required": [
        "driver_id",
        "vehicle_id",
        "order_ids"
      ]
    }
